/*气泡本体*/
body.bubblechat .mes, body.bubblechat .mes[is_user="true"] {
    padding: 230px 12px 30px;
    border-radius: 15px;
    margin-bottom: 5px;
    border: 0px solid var(--SmartThemeBorderColor);
    backdrop-filter: blur(var(--SmartThemeBlurStrength));
    -webkit-backdrop-filter: blur(var(--SmartThemeBlurStrength));
    max-width: 100%;
    margin: 20px auto 45px auto; 
    z-index: 1;
}

.mes {
    --swipeCounterHeight: 15px;
    --swipeCounterMargin: 5px;
    display: flex;
    align-items: flex-start;
    padding: 230px 12px 30px;
    margin: 20px auto 45px auto; 
    width: 100%;
    max-width: 100%;
    position: relative;
    backdrop-filter: blur(var(--SmartThemeBlurStrength));
    -webkit-backdrop-filter: blur(var(--SmartThemeBlurStrength));
    border: 0px solid var(--SmartThemeBorderColor);
    border-radius: 15px;
    z-index: 1;
}


.mes::before {
    content: "";
    position: absolute;
    /* 您可以根据需要调整位置，例如放在顶部 */
    bottom: 0;
    left: 50%;
    transform: translateX(-50%);
    width: 300px;
    height: 30px;
    background-image: url('https://iili.io/qFfR00v.png');
    background-size: 300px 30px; /* 精确填充 */
    background-repeat: no-repeat;
    background-position: center;
    z-index: 1;
    pointer-events: none; /* 防止遮挡点击，如需交互可移除 */
    opacity:0.8;
}

.mes::after {
    content: "";
    position: absolute;
    top: 0; 
    width: 100%;
    padding-top: 10%; 
    height: 0; 
    left: 50%;
    transform: translateX(-50%);
    background-image: url("https://iili.io/qFfsjB2.png");
    background-size: 100% 100%; 
    background-repeat: no-repeat;
    background-position: center;
    z-index: 1;
    pointer-events: none;
}

.mes_text {
    padding-left: 0;
    padding-top: 5px;
    padding-bottom: 5px;
    padding-right: 0;
}

/*感谢秋依老师 */
#form_sheld {
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    background-color:transparent;
}
#chat {
    padding-bottom: 140px;
}


#chat {
    backdrop-filter:none;
}

/* ===== 动画 ===== */
/* 移除原始伪元素 */
#load-spinner ,
#load-spinner::before {
   animation: none;
   content: "";
}

/* 创建新的自定义加载动画 */
#load-spinner::after {
    content: "";
    position: absolute;
    top: 50%;
    left: 50%;
    width: 80px;
    height: 80px;
    background: url('https://iili.io/qFqi1QR.png') center/contain no-repeat;
    transform: translate(-50%, -50%);
    z-index: 1000;
    /* 添加闪烁动画，去除摇晃 */
    animation: blink 2.5s ease-in-out infinite;
}

/* 闪烁动画 */
@keyframes blink {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.2;
  }
}

/* 隐藏原有旋转动画 */
@keyframes custom-spin {
    display: none;
}

/* ===== 字体 ===== */

@font-face {
    font-family: "Jing Hua ";
    src: url("https://files.catbox.moe/138mza.ttf") format("truetype");
}
body, #nonQRFormItems textarea,.mes_text pre code,code , .mes_reasoning pre code,input, select, button {
    font-family: "Jing Hua ", sans-serif;
}

/*代码块*/
.mes_text pre code, .mes_reasoning pre code {
    position: relative;
    display: block;
    overflow-x: auto;
    padding: 1em;
    background-color: rgb(230 230 230 / 30%);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 2px solid rgba(255, 255, 255, 0.2);
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
    color: var(--SmartThemeBodyColor);
}

/*引用块*/
.mes_text blockquote, .mes_reasoning blockquote {
    border-left: 3px solid var(--SmartThemeQuoteColor);
    padding-left: 10px;
    margin: 0;
    background: linear-gradient(135deg, rgb(183 183 183 / 15%), rgb(174 174 174 / 10%), rgb(180 180 180 / 10%));
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border-right: 2px solid rgb(255 255 255 / 20%);
    border-top: 2px solid rgb(255 255 255 / 20%);
    border-bottom: 2px solid rgb(0 0 0 / 20%);
    box-shadow: inset 0 2px 4px rgba(255, 255, 255, 0.1);
}

/* ===== 底部输入栏 ===== */

#send_form {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    width: 100%;
    margin: 0px auto 0px auto; /* 上下边距15px */
    border-radius: 10px;
}

#nonQRFormItems {
    padding: 0;
    border: 0;
    position: relative;
    background-position: center;
    display: flex;
    flex-direction: row;
    column-gap: 5px;
    font-size: var(--bottomFormIconSize);
    order: 25;
    width: 100%;

    /* 设置最小高度为30px，而不是固定高度 */
    min-height: 30px;
    align-items: center; /* 垂直居中 */
    overflow: hidden; /* 隐藏溢出内容 */
}

/* 输入框样式调整 */
#nonQRFormItems textarea {
    flex: 1;
    min-height: 30px; /* 最小高度与容器相同 */
    max-height: 100px; /* 最大高度限制 */
    resize: none; /* 禁止手动调整大小 */
    overflow-y: auto; /* 内容超出时显示滚动条 */
    line-height: normal; /* 保持正常行高 */
    padding: 5px; /* 适当内边距 */
    margin: 0;
    border: none;
    outline: none;
    background: transparent;
}

/* 字体图标容器固定大小 */
#nonQRFormItems .icon-container {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 30px;
    width: 30px; /* 固定宽度 */
    flex-shrink: 0; /* 防止图标被压缩 */
}

#rightSendForm>div:not(.mes_stop), #leftSendForm>div{
    transform: scale(0.6);
}
/* ===== 顶部 ===== */

#top-bar {
    margin:0 auto;
    left: 0;
    right: 0;
    display: inline-block;
    height: 30px; 
    position: absolute;
    box-shadow: none;
    z-index: 3005;
}

.drawer-icon {
    transform: scale(0.6);
}

/*左右翻页*/
.swipes-counter {
    position:absolute;
    opacity: 0.5;
    left: -40px;
    bottom: -8px;
    font-size: 10px;
}

.swipe_right, .swipe_left {
    width: 15px;
    height: 15px;
    opacity: 0.2;
    font-size: 10px;
    bottom:20px;
}

.swipeRightBlock {
    position: absolute;
    right: 5px;
    bottom: 20px;
}

/*拓展标题*/
#extensions_settings .inline-drawer-toggle.inline-drawer-header, 
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header, 
#user-settings-block h4, 
.standoutHeader {
    opacity: 0.95;
    margin-bottom: 8px;
    padding: 8px 12px;
    position: relative;
    border-radius: 5px;
    background: rgba(180, 180, 180, 0.2);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    box-shadow: 
        0 6px 14px -6px rgba(0, 0, 0, 0.25),
        0 2px 4px -2px rgba(0, 0, 0, 0.15),
        inset 0 1px 2px rgba(255, 255, 255, 0.6);
    border: 1px solid rgba(160, 160, 160, 0.3);
    font-weight: 500;
    font-size: 0.95em;
    letter-spacing: 0.2px;
    transition: all 0.2s ease;
}

#extensions_settings .inline-drawer-toggle.inline-drawer-header:hover,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header:hover,
#user-settings-block h4:hover,
.standoutHeader:hover {
    background: rgba(170, 170, 170, 0.25);
    backdrop-filter: blur(10px);
    box-shadow: 
        0 8px 18px -6px rgba(0, 0, 0, 0.3),
        0 3px 6px -2px rgba(0, 0, 0, 0.2),
        inset 0 1px 2px rgba(255, 255, 255, 0.7);
    transform: translateY(-1px);
}

#extensions_settings .inline-drawer-toggle.inline-drawer-header::after,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header::after,
#user-settings-block h4::after,
.standoutHeader::after {
    content: "";
    position: absolute;
    bottom: 6px;
    left: 12px;
    right: 12px;
    height: 1px;
    background: linear-gradient(90deg, transparent, rgba(100, 100, 100, 0.2), transparent);
    opacity: 0.8;
}

.drawer-content select {
    background-color: #bbbbbb2b;
    border-radius: 3px;
}

/*编辑*/
.reasoning_edit_textarea, 
.edit_textarea {
    background: rgba(200, 200, 200, 0.2);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border-left: 2px solid rgba(160, 160, 160, 0.4);
    border-right: 2px solid rgba(160, 160, 160, 0.4);
    border-top: none;
    border-bottom: 1px solid rgba(160, 160, 160, 0.1);
    box-shadow: 
        0 8px 16px -8px rgba(0, 0, 0, 0.2),
        0 4px 8px -4px rgba(0, 0, 0, 0.1),
        inset 0 1px 2px rgba(255, 255, 255, 0.5),
        inset 0 -1px 1px rgba(255, 255, 255, 0.3);
    border-radius: 4px;
    padding: 10px 14px;
    transition: all 0.2s ease;
}

textarea,#customCSS {
    background-color: rgb(0 0 0 / 5%);
}

.text_pole {
    background-color: rgb(170 170 170 / 30%);
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
    align-items: center;
    padding: 0.5em;
    border: none;
    background: rgba(200, 200, 200, 0.15);
    backdrop-filter: blur(6px);
    -webkit-backdrop-filter: blur(6px);
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.1);
    border-radius: 4px;
    transition: all 0.2s ease;
    position: relative;
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt::before {
    content: "";
    position: absolute;
    top: -1px;
    left: -1px;
    right: -1px;
    bottom: -1px;
    border: 1px solid var(--SmartThemeBorderColor);
    border-radius: 5px;
    pointer-events: none;
    opacity: 0.6;
    z-index: 1;
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt.selected,
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt[aria-selected="true"] {
    background: rgba(180, 180, 200, 0.3);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    box-shadow: 0 4px 10px rgba(0, 0, 0, 0.15);
    transform: translateY(-1px);
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt.selected::before,
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt[aria-selected="true"]::before {
    border: 2px solid var(--SmartThemeBorderColor);
    opacity: 0.9;
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled {
    background: rgba(150, 150, 150, 0.08);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    opacity: 0.6;
    box-shadow: none;
    border: none;
    position: relative;
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled::before {
    content: "";
    position: absolute;
    top: -1px;
    left: -1px;
    right: -1px;
    bottom: -1px;
    border: 1px solid var(--white20a);
    border-radius: 5px;
    pointer-events: none;
    opacity: 0.4;
    z-index: 1;
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt:hover:not(.completion_prompt_manager_prompt_disabled) {
    background: rgba(190, 190, 200, 0.22);
    backdrop-filter: blur(7px);
    box-shadow: 0 3px 8px rgba(0, 0, 0, 0.12);
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt > * {
    position: relative;
    z-index: 2;
}
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name, #completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name .prompt-manager-inspect-action {
    color: rgb(140 140 140);
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_name {
    white-space: normal;
    overflow: visible;
    word-wrap: break-word;
    word-break: break-word;
    max-width: 100%;
}

/*警告*/
.reverse_proxy_warning:not(small) {
    color: var(--SmartThemeBodyColor);
    background-color: rgb(209 209 209 / 70%);
}

/*滑块*/
.neo-range-slider {
    background: var(--SmartThemeBodyColor) !important;
    border-radius:  0 !important;
    box-shadow: none !important;
}

.neo-range-input {
    background-color: rgb(190 190 190 / 30%);
}

/*预设计数*/
#completion_prompt_manager .completion_prompt_manager_header div {
    color: var(--SmartThemeBodyColor);
}

#completion_prompt_manager .completion_prompt_manager_header_advanced span {
    filter: none;
}

/*世界书选择框*/
.select2-container .select2-selection--multiple, .select2-container .select2-selection--single {
    background-color: rgb(188 188 188 / 30%);
}

code {
    background-color: rgb(206 204 204 / 40%);
    color: var(--SmartThemeBodyColor);
}

/* 隐藏所有滚动条，保留滚动功能 */
::-webkit-scrollbar {
    display: none;
}

* {
    scrollbar-width: none;
    -ms-overflow-style: none;
}

/*预设正则空间预留*/
#global_scripts_block ,#scoped_scripts_block ,#completion_prompt_manager_list{
    padding-right: 30px;
}

/*热切换*/
#HotSwapWrapper {
    position: relative;
    overflow-x: auto;
    scrollbar-width: thin; /* Firefox */
    scrollbar-color: rgba(255, 182, 193, 0.3) 
}

#HotSwapWrapper::-webkit-scrollbar {
    height: 1px; /* 设置滚动条高度为3px */
}

#HotSwapWrapper::-webkit-scrollbar-track {
    background: transparent; /* 滚动条轨道透明 */
}

#HotSwapWrapper::-webkit-scrollbar-thumb {
    scrollbar-color: rgba(255, 182, 193, 0.3) 
    border-radius: 0; /* 无圆角 */
    border: none; /* 无边框 */
}

#HotSwapWrapper > * {
    flex-shrink: 0;
}
